const resources=shallowRef<Resources>(),project=ref<Project>(emptyProject()),notice=ref(''),loading=ref(true),saving=ref(false),ready=ref(false);
const downloadProgress=ref<GeoDownloadProgress>();let downloadController:AbortController|undefined;
const downloadStatus=computed(()=>{const p=downloadProgress.value;if(!p)return '';if(p.phase==='manifest')return '正在取得资料信息…';if(p.phase==='validate')return '正在校验调查点、地图与论文数据…';if(p.phase==='save')return '正在保存资料…';return `正在下载资料 ${(p.loaded/1e6).toFixed(1)} / ${(p.total/1e6).toFixed(1)} MB`;});
const storage=new LocalAssets('local','geolinguistics');let saved:string|null=null,saveQueue=Promise.resolve(true),timer:ReturnType<typeof setTimeout>|undefined;const controller=new AbortController();
const volume=ref<Volume>('P'),query=ref(''),locationQuery=ref(''),region=ref(''),category=ref(''),sheet=ref('combined'),classFilters=ref(['','','','']),classDepth=ref(3),classSearch=ref('');
