const level=ref<'auto'|'province'|'city'|'district'>('auto'),labels=ref(false),mapCount=ref(1),extraFeatures=ref(defaultSettings().extraFeatures),maps=shallowRef<(MapHandle|undefined)[]>([]);
const extraBoundaries=ref<BoundaryLevel[]>([]),pageBoundaries=computed(()=>currentBoundaries(level.value,project.value.view.zoom,extraBoundaries.value));
const exportFormat=ref<'svg'|'png'>('svg'),exportOptions=ref<MapExportOptions>(defaultMapExportOptions([])),exportBusy=ref(false);
function openExport(format:'svg'|'png'){exportFormat.value=format;exportOptions.value=defaultMapExportOptions(pageBoundaries.value);modal.value='export';}
function setMapRef(index:number,value:unknown){if(value)maps.value[index]=value as MapHandle;else if(index<maps.value.length)maps.value[index]=undefined;while(maps.value.length&&!maps.value.at(-1))maps.value.pop();}
const mapArea=ref<HTMLDivElement>(),mapFullscreenButton=ref<HTMLButtonElement>(),mapFullscreen=ref(false);
async function toggleMapFullscreen(){
 try{if(document.fullscreenElement===mapArea.value)await document.exitFullscreen();else await mapArea.value?.requestFullscreen();}
 catch(e){reportError('无法切换地图全屏：'+(e as Error).message);}
}
function mapFullscreenChanged(){const was=mapFullscreen.value;mapFullscreen.value=!!mapArea.value&&document.fullscreenElement===mapArea.value;if(was&&!mapFullscreen.value)void nextTick(()=>mapFullscreenButton.value?.focus());}
function leaveMapFullscreen(){if(mapFullscreen.value)void document.exitFullscreen().catch(e=>reportError('无法退出地图全屏：'+(e as Error).message));}
watch(()=>props.active,active=>{if(!active)leaveMapFullscreen();});
function mapHandle(index:number){const handle=maps.value[index];if(!handle)throw Error('地图尚未载入，请重新载入资料。');return handle;}
const paperMode=ref('rgb'),clusters=ref(5),matrixName=ref('main'),matrix=shallowRef<Float64Array>(),matrixBusy=ref(false),compareStatus=ref('different'),compareVolume=ref<Volume|''>(''),compareOpen=ref(false),comparisonPage=ref(0);let matrixRequest=0;
const selectedSite=ref(''),selectedClass=ref(''),tablePage=ref(0),tableOpen=ref(true),onlySelected=ref(false),onlyViewport=ref(false),viewExtent=ref<number[]>([]),fit=ref<{extent:number[];nonce:number}>();
const drawMode=ref<'Polygon'|'LineString'|'point'|''>(''),modal=ref(''),editText=ref(''),editValues=ref<string[]>([]),labelCode=ref(''),labelText=ref('');
const bookmarksOnly=ref(false);
const featureDetail=computed<FeatureDetail>({get:()=>project.value.featureDetail??'broad',set:value=>{project.value.featureDetail=value;}});
