function legendRecords(f:AtlasFeature,visible=false){return (visible?visibleSites.value:baseSites.value).map(({site,index})=>({siteId:site.id,value:observation(data.value,project.value,f.id,index)}));}
function personalObservationCount(f:AtlasFeature){return visibleSites.value.filter(({index})=>isObservationEdited(data.value,project.value,f.id,index)).length;}
function reportError(message:string,retry:''|'load'|'save'|'map'=''){error.value=message;errorRetry.value=retry;}
async function retryError(){const action=errorRetry.value;if(action==='save'){await save();return;}if(action==='load'){await load();return;}if(action==='map'){try{const current=Array.from({length:project.value.mode==='features'?mapFeatures.value.length:1},(_,index)=>mapHandle(index));if(!current.length)throw Error('地图尚未载入，请重新载入资料。');await Promise.all(current.map(map=>map.reload()));if(errorRetry.value==='map')error.value='';}catch(e){reportError((e as Error).message,'map');}}}
