const pointDraft=ref({id:'',name:'',lon:113.56,lat:22.27,value:'',note:''}),pendingProject=ref<Project>();
const importRows=ref<string[][]>([]),importColumns=ref([0,1,2,3,4]),importBook=shallowRef<Awaited<ReturnType<typeof readTableFile>>>(),importSheet=ref(0);
const past=ref<string[]>([]),future=ref<string[]>([]);let replaying=false,lastUndo=JSON.stringify(project.value);
const data=computed(()=>resources.value!);const feature=computed(()=>data.value?.catalog.features.find(f=>f.id===project.value.feature)??data.value?.catalog.features[0]);
const adminIndex=computed(()=>new Map((data.value?.admin??[]).map(a=>[a.id,a])));
const attributions=computed(()=>mapAttributions(data.value?.admin??[]));
const regionSelector=ref<HTMLSelectElement>();
const regionState=computed(()=>regionSelection(region.value,adminIndex.value));
const selectedAdmin=computed(()=>adminIndex.value.get(region.value));
const provinces=computed(()=>data.value?.admin.filter(a=>a.level==='province')??[]);
const selectedRegionPath=computed(()=>regionPath(region.value,adminIndex.value));
const provinceId=computed(()=>selectedRegionPath.value[0]?.id??'');
const nextRegionId=computed(()=>selectedRegionPath.value[1]?.id??'');
const subregionId=computed(()=>selectedRegionPath.value[2]?.id??'');
const nextRegions=computed(()=>provinceId.value?data.value?.admin.filter(a=>a.parent===provinceId.value)??[]:[]);
const subregions=computed(()=>nextRegionId.value?data.value?.admin.filter(a=>a.parent===nextRegionId.value)??[]:[]);
const regionAvailability=computed(()=>selectedAdmin.value&&((provinceId.value&&!nextRegions.value.length)||(nextRegionId.value&&!subregions.value.length))?`当前资料可按${selectedAdmin.value.name}整体查看，未提供下一级地区。`:'');
const reviewedFeatures=computed(()=>data.value?.catalog.features.filter(isReadable)??[]);
const availableFeatures=computed(()=>featureScope.value==='all'?data.value?.catalog.features??[]:reviewedFeatures.value);
const featureList=computed(()=>availableFeatures.value.filter(f=>f.volume===volume.value&&(!bookmarksOnly.value||project.value.bookmarks?.includes(f.id))&&(f.title+f.id+f.number).toLowerCase().includes(query.value.trim().toLowerCase())));
function changeFeatureScope(value:'reviewed'|'all'){featureScope.value=value;if(value==='reviewed'){if(!isReadable(feature.value)&&reviewedFeatures.value.length)chooseFeature(reviewedFeatures.value.find(f=>f.volume===volume.value)?.id??reviewedFeatures.value[0].id);extraFeatures.value=extraFeatures.value.map((id,i)=>availableFeatures.value.some(f=>f.id===id)?id:defaultSettings().extraFeatures[i]);}}
function changeVolume(v:Volume){volume.value=v;const first=availableFeatures.value.find(f=>f.volume===v);if(first&&feature.value.volume!==v)chooseFeature(first.id);}
const siteIndex=computed(()=>new Map((data.value?.sites??[]).map((s,i)=>[s.id,i])));
const selectedIndices=computed(()=>project.value.selected.map(id=>siteIndex.value.get(id)).filter((i):i is number=>i!==undefined));
const currentSite=computed(()=>data.value?.sites.find(s=>s.id===selectedSite.value));
const currentSiteIndex=computed(()=>siteIndex.value.get(selectedSite.value)??-1);
const originalClassRows=computed(()=>data.value?.classification.sheets.find(s=>s.id===sheet.value)?.rows??[]);
const classRows=computed(()=>originalClassRows.value.filter(r=>{const v=classValues(r,project.value);return (!regionState.value.effective||inRegion(r.admin,regionState.value.effective,adminIndex.value)||(selectedAdmin.value?.level==='province'&&v[1]===selectedAdmin.value.name))&&classFilters.value.every((f,i)=>classFilterMatches(f,v[6+i]))&&(!classSearch.value||v.join(' ').includes(classSearch.value));}));
const currentClass=computed(()=>originalClassRows.value.find(r=>r.id===selectedClass.value));
const classOptions=computed(()=>[0,1,2,3].map(depth=>[...new Set(originalClassRows.value.filter(r=>classFilters.value.slice(0,depth).every((f,i)=>classFilterMatches(f,classValues(r,project.value)[6+i]))).map(r=>classValues(r,project.value)[6+depth]||unclassifiedClassFilter))].sort((a,b)=>a.localeCompare(b,'zh'))));
const countedPaths=computed(()=>diversity(classRows.value,project.value,classDepth.value));
const provinceRanking=computed(()=>{const grouped=new Map<string,ClassificationRow[]>();for(const r of originalClassRows.value){const name=classValues(r,project.value)[1];grouped.set(name,[...(grouped.get(name)??[]),r]);}return [...grouped].map(([name,rows])=>({name,count:diversity(rows,project.value,classDepth.value).length,rows:rows.length})).sort((a,b)=>b.count-a.count);});
const baseSites=computed(()=>{if(!data.value)return [];return data.value.sites.map((site,index)=>({site,index})).filter(({site})=>inRegion(site.admin,regionState.value.effective,adminIndex.value)&&(!locationQuery.value||site.name.includes(locationQuery.value)||site.id===locationQuery.value)&&(!onlySelected.value||project.value.selected.includes(site.id))&&(!onlyViewport.value||viewExtent.value.length===4&&site.lon>=viewExtent.value[0]&&site.lon<=viewExtent.value[2]&&site.lat>=viewExtent.value[1]&&site.lat<=viewExtent.value[3]));});
const visibleSites=computed(()=>project.value.mode!=='features'||!category.value?baseSites.value:baseSites.value.filter(({index,site})=>{const codes=displayCodes(observation(data.value,project.value,project.value.feature,index),feature.value,featureDetail.value,site.id);return category.value===pendingBroadSites?codes.some(code=>!isBroadCategory(code)):codes.includes(category.value);}));
const activeFilters=computed(()=>{const items:string[]=[];if(regionState.value.effective)items.push(selectedAdmin.value?.name??'行政范围');if(project.value.mode==='classification'){if(classSearch.value)items.push('搜索 '+classSearch.value);if(classFilters.value.some(Boolean))items.push('方言分类');}else if(project.value.mode!=='custom'){if(locationQuery.value)items.push('调查点 '+locationQuery.value);if(onlySelected.value)items.push('仅选中');if(onlyViewport.value)items.push('当前视野');if(project.value.mode==='features'&&category.value)items.push('类别 '+categoryLabel(category.value));}return items;});
function clearFilters(){region.value='';locationQuery.value='';category.value='';classSearch.value='';classFilters.value=['','','',''];onlySelected.value=false;onlyViewport.value=false;tablePage.value=0;}
function clearSelection(){project.value.selected=[];selectedSite.value='';onlySelected.value=false;}
