const pendingSites=computed(()=>feature.value&&featureDetail.value==='broad'?broadPendingCount(legendRecords(feature.value),feature.value):0);
const classMarkers=computed(()=>{const byAdmin=new Map<string,ClassificationRow[]>();for(const r of classRows.value)if(r.admin)byAdmin.set(r.admin,[...(byAdmin.get(r.admin)??[]),r]);return [...byAdmin].map(([id,rows])=>{const a=adminIndex.value.get(id)!;const paths=[...new Set(rows.map(r=>classPath(classValues(r,project.value),classDepth.value)))];return {id:'admin:'+id,name:a.name,lon:a.center[0],lat:a.center[1],label:paths.join('；'),color:paths.length>1?'#647d8b':categoryColor(paths[0]),multi:paths.length>1,chosen:project.value.selected.includes('admin:'+id),selected:region.value===id||project.value.selected.includes('admin:'+id)};});});
const polygonColors=computed(()=>project.value.mode==='classification'?classificationPolygonColors(classRows.value,project.value,adminIndex.value,classDepth.value):{});
const mdsRanges=computed(()=>[0,1,2].map(d=>{const vals=data.value?.paper.points.map(p=>p.mds[d])??[0,1];return [Math.min(...vals),Math.max(...vals)];}));
function mdsScaled(index:number,d:number){const [a,b]=mdsRanges.value[d];return (data.value.paper.points[index].mds[d]-a)/(b-a||1);}
function paperValue(index:number){const p=data.value.paper.points[index];return paperMode.value==='rgb'?'MDS RGB':paperMode.value.startsWith('d')?p.mds[Number(paperMode.value[1])-1].toFixed(5):p[paperMode.value as 'sharp'|'heat'][clusters.value-2];}
function paperColor(index:number){if(paperMode.value==='rgb')return '#'+[0,1,2].map(d=>Math.round(mdsScaled(index,d)*255).toString(16).padStart(2,'0')).join('');if(paperMode.value.startsWith('d')){const d=Number(paperMode.value[1])-1;return dimensionColor(data.value.paper.points[index].mds[d],mdsRanges.value[d]);}return data.value.paper.colors[paperMode.value]?.[clusters.value]?.[paperValue(index)]??'#9099a2';}
function pointsFor(f:AtlasFeature):MapPoint[]{if(project.value.mode==='classification')return classMarkers.value;if(project.value.mode==='custom')return project.value.customSites.map(p=>({...p,color:categoryColor(p.value),label:p.value,chosen:project.value.selected.includes(p.id),selected:selectedSite.value===p.id||project.value.selected.includes(p.id)}));return visibleSites.value.map(({site,index})=>{const value=observation(data.value,project.value,f.id,index);return {...site,...(project.value.mode==='paper'?{color:paperColor(index)}:pointAppearance(value,f,featureDetail.value,site.id)),label:project.value.mode==='paper'?paperValue(index):valueLabel(value,f,site.id),chosen:project.value.selected.includes(site.id),selected:project.value.selected.includes(site.id)||site.id===selectedSite.value};});}
const mapFeatures=computed(()=>feature.value?[feature.value,...extraFeatures.value.slice(0,mapCount.value-1).map(id=>data.value.catalog.features.find(f=>f.id===id)??feature.value)]:[]);
const mapPoints=computed(()=>mapFeatures.value.map(pointsFor));
const selectedMapPointCount=computed(()=>(mapPoints.value[0]??[]).filter(point=>point.chosen??point.selected).length);
function categoryLabel(code:string,f=feature.value){return displayText(code,f,project.value,featureDetail.value);}
function valueLabel(value:string|null,f=feature.value,siteId?:string){return displayValue(value,f,project.value,featureDetail.value,siteId);}
