const legend=computed(()=>{if(!feature.value)return [];if(project.value.mode==='classification')return [...countedPaths.value.map(p=>({code:p.path,label:p.path,count:p.rows.length,color:categoryColor(p.path)})),...(classMarkers.value.some(p=>p.multi)?[{code:'mixed',label:'同一行政单元兼有多类',count:classMarkers.value.filter(p=>p.multi).length,color:'#647d8b'}]:[])];if(project.value.mode==='custom')return categoryCounts(project.value.customSites.map(p=>p.value)).map(p=>({...p,label:p.code,color:categoryColor(p.code)}));if(project.value.mode==='paper'){if(paperMode.value==='rgb'||paperMode.value.startsWith('d'))return [];const counts=categoryCounts(baseSites.value.map(s=>paperValue(s.index)));return counts.map(c=>({...c,label:c.code,color:data.value.paper.colors[paperMode.value]?.[clusters.value]?.[c.code]??'#9099a2'}));}return displayCounts(legendRecords(feature.value),feature.value,featureDetail.value).filter(c=>featureDetail.value==='fine'||isBroadCategory(c.code)).map(c=>({...c,label:categoryLabel(c.code),color:displayColor(c.code,feature.value,featureDetail.value)}));});
const allSiteFeatures=computed(()=>currentSiteIndex.value<0?[]:data.value.catalog.features.map(f=>({feature:f,value:observation(data.value,project.value,f.id,currentSiteIndex.value)})));
const comparisonRows=computed(()=>data.value?compareFeatures(data.value,project.value,selectedIndices.value.slice(0,8)):[]);
