const comparisonPageCount=computed(()=>Math.max(1,Math.ceil(comparisons.value.length/60)));
const comparisonPageRows=computed(()=>comparisons.value.slice(comparisonPage.value*60,(comparisonPage.value+1)*60));
watch(comparisons,()=>{comparisonPage.value=0;});
const comparisonCounts=computed(()=>({same:groupedComparisons.value.filter(r=>r.status==='same').length,different:groupedComparisons.value.filter(r=>r.status==='different').length,missing:groupedComparisons.value.filter(r=>r.status==='missing').length}));
const comparisonNames={same:'记录相同',different:'记录不同',missing:'含缺值'};
function openComparison(){comparisonPage.value=0;compareOpen.value=true;void loadMatrix();}
function comparePair(id:string){if(!currentSite.value||id===currentSite.value.id)return;project.value.selected=[currentSite.value.id,id];openComparison();}
function replaceComparedSite(index:number,id:string){const ids=project.value.selected.slice(0,8);if(ids.includes(id)&&ids[index]!==id)return;ids[index]=id;project.value.selected=ids;}
function exportComparison(){const chosenSites=selectedIndices.value.slice(0,8).map(i=>data.value.sites[i]);const rows:unknown[][]=[['卷','图号','语言特征','记录比较',...chosenSites.flatMap(s=>[s.name+' · 编码',s.name+' · 含义']),'原书PDF页','来源'],...comparisons.value.map(r=>[volumeNames[r.feature.volume],r.feature.number,r.feature.title,comparisonNames[r.status],...r.values.flatMap((v,i)=>[v,valueLabel(v,r.feature,chosenSites[i].id)]),r.feature.page,'Huang et al. 2024 / Zenodo 10697975'])];void exportFile('调查点特征比较.csv',new Blob([csvText(rows)],{type:'text/csv;charset=utf-8'}));}
const nearby=computed(()=>matrix.value&&currentSiteIndex.value>=0?nearest(matrix.value,currentSiteIndex.value,15):[]);
const count=computed(()=>project.value.mode==='classification'?classRows.value.length:project.value.mode==='custom'?project.value.customSites.length:visibleSites.value.length);
const pageSites=computed(()=>visibleSites.value.slice(tablePage.value*60,(tablePage.value+1)*60));const pageClasses=computed(()=>classRows.value.slice(tablePage.value*60,(tablePage.value+1)*60));
function changeMode(mode:Mode){if(mode!=='custom')drawMode.value='';project.value.mode=mode;category.value='';tablePage.value=0;if(mode==='paper')void loadMatrix();}
function chooseFeature(id:string){const chosen=data.value.catalog.features.find(f=>f.id===id);if(chosen&&!isReadable(chosen))featureScope.value='all';project.value.feature=id;category.value='';tablePage.value=0;volume.value=data.value.catalog.features.find(f=>f.id===id)?.volume??'P';}
function chooseRegion(id:string,zoom=true){region.value=id;tablePage.value=0;if(!id){china();return;}const a=adminIndex.value.get(id);if(a&&zoom)fit.value={extent:a.extent,nonce:Date.now()};}
function chooseSite(id:string){if(id.startsWith('admin:')){if(!project.value.selected.includes(id))project.value.selected=[...project.value.selected,id];chooseRegion(id.slice(6),false);return;}selectedSite.value=id;const s=data.value.sites.find(s=>s.id===id);if((s||project.value.customSites.some(site=>site.id===id))&&!project.value.selected.includes(id))project.value.selected=[...project.value.selected,id];}
function focusSite(id:string){chooseSite(id);const s=data.value.sites.find(s=>s.id===id)??project.value.customSites.find(s=>s.id===id);if(s)fit.value={extent:[s.lon-.2,s.lat-.15,s.lon+.2,s.lat+.15],nonce:Date.now()};}
function chooseClass(row:ClassificationRow){selectedClass.value=row.id;if(row.admin){const a=adminIndex.value.get(row.admin);if(a)fit.value={extent:a.extent,nonce:Date.now()};}}
