function china(){region.value='';fit.value={extent:[73,3,135,54],nonce:Date.now()};}
function restoreView(){fit.value=undefined;if(isLegacyWorldView(project.value.view)){project.value.view=emptyProject().view;fit.value={extent:[73,3,135,54],nonce:Date.now()};}}
function filterClass(depth:number,value:string){classFilters.value=classFilters.value.map((v,i)=>i<depth?v:i===depth?value:'');tablePage.value=0;}
function selectPath(path:string){classFilters.value=path.split(' / ').map(v=>v==='未分'?unclassifiedClassFilter:v);while(classFilters.value.length<4)classFilters.value.push('');modal.value='';tablePage.value=0;}
const settings=computed(()=>({volume:volume.value,query:query.value,locationQuery:locationQuery.value,region:region.value,category:category.value,sheet:sheet.value,classFilters:classFilters.value,classDepth:classDepth.value,classSearch:classSearch.value,level:level.value,extraBoundaries:extraBoundaries.value,labels:labels.value,mapCount:mapCount.value,extraFeatures:extraFeatures.value,paperMode:paperMode.value,clusters:clusters.value,matrixName:matrixName.value,onlySelected:onlySelected.value,onlyViewport:onlyViewport.value,tableOpen:tableOpen.value,selectedSite:selectedSite.value,selectedClass:selectedClass.value}));
function restoreSettings(){const s=project.value.settings??{...defaultSettings(),volume:feature.value?.volume??'P'};volume.value=s.volume;query.value=s.query;locationQuery.value=s.locationQuery;region.value=s.region;category.value=s.category;sheet.value=s.sheet;classFilters.value=s.classFilters;classDepth.value=s.classDepth;classSearch.value=s.classSearch;level.value=s.level;extraBoundaries.value=s.extraBoundaries??[];labels.value=s.labels;mapCount.value=s.mapCount;extraFeatures.value=s.extraFeatures;paperMode.value=s.paperMode;clusters.value=s.clusters;matrixName.value=s.matrixName;onlySelected.value=s.onlySelected;onlyViewport.value=s.onlyViewport;tableOpen.value=s.tableOpen;selectedSite.value=s.selectedSite;selectedClass.value=s.selectedClass;if(feature.value&&!isReadable(feature.value))featureScope.value='all';if(featureScope.value==='reviewed')extraFeatures.value=extraFeatures.value.map((id,i)=>reviewedFeatures.value.some(f=>f.id===id)?id:defaultSettings().extraFeatures[i]);}
watch(settings,value=>{if(ready.value)project.value.settings=JSON.parse(JSON.stringify(value));},{deep:true});
async function chooseData(event:Event){
 const input=event.target as HTMLInputElement,files=Array.from(input.files??[]);input.value='';if(!files.length)return;
 await replaceData(()=>geoPort.useDirectory(files));
}
async function downloadData(){
 if(loading.value)return;downloadController=new AbortController();error.value='';notice.value='';
 try{await replaceData(()=>geoPort.download(value=>{downloadProgress.value=value;},downloadController!.signal));}
 finally{downloadController=undefined;downloadProgress.value=undefined;}
}
async function replaceData(operation:()=>Promise<void>){
 const hadProject=ready.value,hadMatrix=!!matrix.value||matrixBusy.value;loading.value=true;
 try{
  if(hadProject&&!await save())return;
  await operation();++matrixRequest;matrix.value=undefined;matrixBusy.value=false;
  // Replacing resources must never replace the live draft with an earlier disk snapshot.
  if(hadProject){resources.value=await geoPort.load(controller.signal);if(hadMatrix||project.value.mode==='paper'||compareOpen.value)await loadMatrix();}
  else if(!await load())return;
  notice.value='资料已载入并保存在本机。';
 }catch(e){if((e as Error).name==='AbortError')notice.value='下载已取消，原有资料和编辑已保留。';else error.value=(e as Error).message;}finally{loading.value=false;}
}
async function load(){loading.value=true;error.value='';try{resources.value=await geoPort.load(controller.signal);const stored=await storage.value<string>(props.stateKey);if(stored){project.value=validateProject(JSON.parse(stored));saved=stored;restoreView();}else{fit.value={extent:[73,3,135,54],nonce:Date.now()};}restoreSettings();lastUndo=JSON.stringify(project.value);ready.value=true;if(project.value.mode==='paper')await loadMatrix();return true;}catch(e){if(!controller.signal.aborted&&(e as Error).name!=='GeoDataUnavailableError')reportError((e as Error).message,'load');return false;}finally{loading.value=false;}}
async function save(){if(!ready.value)return false;clearTimeout(timer);saveQueue=saveQueue.then(async()=>{const value=JSON.stringify(project.value);if(value===saved){if(errorRetry.value==='save')error.value='';return true;}saving.value=true;try{await storage.compare(props.stateKey,saved,value);saved=value;emit('dirty',JSON.stringify(project.value)!==saved);if(errorRetry.value==='save')error.value='';return true;}catch(e){reportError('工程保存失败：'+(e as Error).message,'save');emit('dirty',true);return false;}finally{saving.value=false;}});return saveQueue;}
watch(project,()=>{if(!ready.value)return;emit('dirty',true);clearTimeout(timer);timer=setTimeout(()=>{void save();},400);},{deep:true});
function checkpoint(){if(replaying)return;const current=JSON.stringify(project.value);if(current===lastUndo)return;past.value.push(lastUndo);if(past.value.length>40)past.value.shift();future.value=[];lastUndo=current;}
function restoreHistory(raw:string){const p=validateProject(JSON.parse(raw));project.value={...project.value,name:p.name,edits:p.edits,classEdits:p.classEdits,labels:p.labels,customSites:p.customSites,drawings:p.drawings,bookmarks:p.bookmarks??[]};}
function undo(){if(!past.value.length)return;replaying=true;future.value.push(JSON.stringify(project.value));restoreHistory(past.value.pop()!);lastUndo=JSON.stringify(project.value);replaying=false;}
function redo(){if(!future.value.length)return;past.value.push(JSON.stringify(project.value));restoreHistory(future.value.pop()!);lastUndo=JSON.stringify(project.value);}
async function loadMatrix(){matrix.value=undefined;matrixBusy.value=true;const requested=matrixName.value,request=++matrixRequest;try{const result=await geoPort.matrix(requested);if(matrixName.value===requested&&request===matrixRequest)matrix.value=result;}catch(e){if(request===matrixRequest)error.value=(e as Error).message;}finally{if(request===matrixRequest)matrixBusy.value=false;}}
watch(matrixName,()=>{void loadMatrix();});watch([region,category,locationQuery,onlySelected,onlyViewport,sheet,classFilters,classSearch],()=>{tablePage.value=0;},{deep:true});
function editObservation(){editText.value=observation(data.value,project.value,feature.value.id,currentSiteIndex.value)??'';modal.value='observation';}
function applyObservation(){if(!editText.value.trim()){error.value='请填写类别，多个变体以 # 分隔。';return;}project.value.edits[selectedSite.value+':'+feature.value.id]=editText.value.trim();checkpoint();modal.value='';}
function restoreObservation(){delete project.value.edits[selectedSite.value+':'+feature.value.id];checkpoint();}
function editClass(){if(!currentClass.value)return;editValues.value=[...classValues(currentClass.value,project.value)];modal.value='classification';}
function applyClass(){if(!currentClass.value)return;project.value.classEdits[currentClass.value.id]=[...editValues.value];checkpoint();modal.value='';}
function newPoint(lon=113.56,lat=22.27){pointDraft.value={id:'',name:'',lon,lat,value:'',note:''};modal.value='point';drawMode.value='';}
function editPoint(id:string){const p=project.value.customSites.find(s=>s.id===id);if(p){pointDraft.value={...p};modal.value='point';}}
function applyPoint(){const p=pointDraft.value;if(!p.name.trim()||!Number.isFinite(p.lon)||!Number.isFinite(p.lat)||Math.abs(p.lon)>180||Math.abs(p.lat)>85){error.value='请填写地点名称和有效经纬度。';return;}const value={...p,id:p.id||'user:'+crypto.randomUUID(),admin:null};const i=project.value.customSites.findIndex(s=>s.id===p.id);if(i>=0)project.value.customSites[i]=value;else project.value.customSites.push(value);checkpoint();modal.value='';}
function addDrawing(value:object){project.value.drawings=value;drawMode.value='';checkpoint();}
async function exportFile(name:string,blob:Blob){try{const result=await geoPort.save(name,blob);notice.value=result==='saved'?'文件已保存。':result==='requested'?'已打开保存操作。':'已取消保存。';}catch(e){error.value=(e as Error).message;}}
function exportProject(){void exportFile(project.value.name+'.ptb-map.json',new Blob([JSON.stringify(project.value,null,2)],{type:'application/json'}));}
async function importProject(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];input.value='';if(!file)return;try{if(file.size>20_000_000)throw Error('工程文件超过 20 MB。');pendingProject.value=validateProject(JSON.parse(await file.text()));modal.value='import-project';}catch(e){error.value=(e as Error).message;}}
function applyProject(){if(pendingProject.value){project.value=pendingProject.value;drawMode.value='';restoreView();restoreSettings();checkpoint();modal.value='';if(project.value.mode==='paper'||compareOpen.value)void loadMatrix();}}
async function importTable(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];input.value='';if(!file)return;try{importBook.value=await readTableFile(file);importSheet.value=0;importRows.value=await importBook.value.rows(0);modal.value='import-table';}catch(e){error.value=(e as Error).message;}}
async function changeImportSheet(){try{importRows.value=await importBook.value!.rows(importSheet.value);}catch(e){error.value=(e as Error).message;}}
const importPreview=computed(()=>importRows.value.slice(1).filter(row=>row.some(Boolean)).map((row,i)=>{const [name,lon,lat,value,note]=importColumns.value.map(c=>row[c]??'');return {id:'import:'+i,name,lon:Number(lon),lat:Number(lat),value,note,admin:null,valid:!!name&&lon.trim()!==''&&lat.trim()!==''&&Number.isFinite(Number(lon))&&Number.isFinite(Number(lat))&&Math.abs(Number(lon))<=180&&Math.abs(Number(lat))<=85};}));
function applyTable(){if(!importPreview.value.length||importPreview.value.some(r=>!r.valid)){error.value='请先修正无效的坐标或名称，表格尚未导入。';return;}project.value.customSites.push(...importPreview.value.map(({valid,...p})=>({...p,id:'user:'+crypto.randomUUID()})));project.value.mode='custom';checkpoint();modal.value='';}
function exportTable(){const rows:unknown[][]=project.value.mode==='classification'?[['来源表','原行',...data.value.classification.columns,'匹配行政区'],...classRows.value.map(r=>[r.sheet,r.row,...classValues(r,project.value),r.admin??''])]:project.value.mode==='paper'?[['地点编号','调查点','经度','纬度','结果图层','原始结果','来源'],...visibleSites.value.map(({site,index})=>[site.id,site.name,site.lon,site.lat,paperMode.value,paperMode.value==='rgb'?data.value.paper.points[index].mds.join(' / '):paperMode.value.startsWith('d')?data.value.paper.points[index].mds[Number(paperMode.value[1])-1]:paperValue(index),'Huang et al. 2024 / Zenodo 10697975'])]:project.value.mode==='custom'?[['地点','经度','纬度','类别','备注'],...project.value.customSites.map(p=>[p.name,p.lon,p.lat,p.value,p.note])]:[['地点编号','调查点','经度','纬度','特征','类别编码','具体含义','原始值','原书PDF页','图例说明','来源','显示层级'],...visibleSites.value.map(({site,index})=>[site.id,site.name,site.lon,site.lat,feature.value.title,observation(data.value,project.value,feature.value.id,index),valueLabel(observation(data.value,project.value,feature.value.id,index),feature.value,site.id),data.value.observations[feature.value.id].raw[index]?.raw??data.value.observations[feature.value.id].values[index],feature.value.page,[feature.value.categoryNote,featureDetail.value==='broad'?feature.value.groupNote:''].filter(Boolean).join('；'),'Huang et al. 2024 / Zenodo 10697975'+(isObservationEdited(data.value,project.value,feature.value.id,index)?'；含个人校订':''),featureDetail.value==='broad'?'大类':'细类'])];void exportFile('语言地图数据.csv',new Blob([csvText(rows)],{type:'text/csv;charset=utf-8'}));}
async function exportMap(format:'svg'|'png'){if(exportBusy.value)return;exportBusy.value=true;try{const options:MapExportOptions={...exportOptions.value,boundaries:[...exportOptions.value.boundaries]};await Promise.all(Array.from({length:project.value.mode==='features'?mapFeatures.value.length:1},(_,i)=>mapHandle(i).prepareExport(options)));await document.fonts.load('14px PTB-Doulos');await document.fonts.ready;const title=project.value.mode==='classification'?'井韶子整理 · 县级方言归属':project.value.mode==='paper'?'论文结果 · '+paperMode.value:project.value.mode==='custom'?project.value.name:feature.value.title;const source=project.value.mode==='custom'?'用户研究工程 · '+project.value.name:project.value.mode==='classification'?'井韶子整理；《中国语言地图集（第2版）汉语方言卷》；来源表：'+sheet.value:'Huang 等（2024），Zenodo 10697975；《汉语方言地图集》；调查 2000–2008';const panels=(project.value.mode==='features'?mapFeatures.value:[feature.value]).map((f,i)=>{
 const items=project.value.mode==='features'?displayCounts(legendRecords(f,true),f,featureDetail.value).filter(c=>featureDetail.value==='fine'||isBroadCategory(c.code)).map(v=>({label:displayText(v.code,f,project.value,featureDetail.value,true)+' · '+v.count+' 个地点',color:displayColor(v.code,f,featureDetail.value)})):legend.value.map(v=>({label:v.label+' · '+v.count,color:v.color}));
 return mapHandle(i).exportSvg(project.value.mode==='features'?f.title:title,items,source+(project.value.mode==='features'?'；'+(featureDetail.value==='broad'?'大类分布':'细类分布')+'；'+volumeNames[f.volume]+'卷图 '+f.number+'，PDF 第 '+f.page+' 页'+(f.categoryNote?'。'+f.categoryNote:'')+(featureDetail.value==='broad'&&f.groupNote?'。'+f.groupNote:'')+(featureDetail.value==='broad'&&f.groups?.some(g=>g.labelKind==='summary')?'。大类名称含对原图共同特征的概括。':'')+(featureDetail.value==='broad'&&broadPendingCount(legendRecords(f,true),f)?'。'+broadPendingCount(legendRecords(f,true),f)+' 个地点含待核记录：空心点表示大类尚未对应，虚线边框表示同点部分记录尚待对应；未计入已核大类图例。':featureDetail.value==='fine'&&!hasCompleteMeanings(f)?'。未核细类保留编码。':'')+(project.value.labels[f.id]&&Object.values(project.value.labels[f.id]).some(v=>v.trim())?'。含用户填写的类别释义。':'')+(personalObservationCount(f)?'。含个人校订（'+personalObservationCount(f)+' 个地点）。':''):''),options);
 });
 const filename=title;let svg=composeMapSvgs(panels);const font=await fetch(ipaFontUrl);if(!font.ok)throw Error('音标字体读取失败。');
 const fontData=await new Promise<string>((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result));r.onerror=()=>reject(Error('音标字体读取失败。'));void font.blob().then(b=>r.readAsDataURL(b));});
 const xml=(v:string)=>v.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;');
 svg=svg.replace(/(<svg[^>]*>)/,'$1'+`<metadata>${xml(ipaFontLicense)}</metadata><style>@font-face{font-family:PTB-Map-IPA;src:url(${fontData})}.nearby{display:flex;align-items:center;gap:8px}.nearby>small{margin-left:auto}.comparison-sites,.comparison-controls{display:flex;flex-wrap:wrap;gap:12px;margin-bottom:12px}.comparison-sites label,.comparison-controls label{display:flex;align-items:center;gap:6px}.comparison-sites select{max-width:180px}.comparison-summary{font-variant-numeric:tabular-nums}
</style>`);
 if(format==='svg'){await exportFile(filename+'.svg',new Blob([svg],{type:'image/svg+xml'}));modal.value='';return;}const url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml'}));try{const image=new Image();image.src=url;await image.decode();const canvas=document.createElement('canvas');canvas.width=image.naturalWidth*2;canvas.height=image.naturalHeight*2;canvas.getContext('2d')!.drawImage(image,0,0,canvas.width,canvas.height);const blob=await new Promise<Blob>((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(Error('图像导出失败。')),'image/png'));await exportFile(filename+'.png',blob);modal.value='';}finally{URL.revokeObjectURL(url);}}catch(e){error.value=(e as Error).message;}finally{exportBusy.value=false;}}
function rawValue(){const i=currentSiteIndex.value;return i<0?'':data.value.observations[feature.value.id].raw[i]?.raw??data.value.observations[feature.value.id].values[i];}
function keydown(event:KeyboardEvent){if(props.active&&event.key==='Escape'&&mapFullscreen.value){event.preventDefault();leaveMapFullscreen();return;}if(!props.active||(event.target as HTMLElement).matches('input,textarea,select'))return;if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='z'){event.preventDefault();event.shiftKey?redo():undo();}if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='s'){event.preventDefault();void save();}}
function beforeUnload(event:BeforeUnloadEvent){if(ready.value&&JSON.stringify(project.value)!==saved){event.preventDefault();event.returnValue='';}}
onMounted(()=>{void load();document.addEventListener('fullscreenchange',mapFullscreenChanged);window.addEventListener('keydown',keydown);window.addEventListener('beforeunload',beforeUnload);});onBeforeUnmount(()=>{leaveMapFullscreen();document.removeEventListener('fullscreenchange',mapFullscreenChanged);controller.abort();downloadController?.abort();clearTimeout(timer);maps.value.length=0;window.removeEventListener('keydown',keydown);window.removeEventListener('beforeunload',beforeUnload);});defineExpose({save});
</script>

<template>
<ModuleFrame label="语言地图" fit unified class="language-atlas">
 <div class="atlas-toolbar"><div class="mode-tabs" role="tablist" aria-label="地图资料"><button v-for="tab in ([['classification','方言分布'],['paper','方言相似性'],['features','语言现象'],['custom','我的研究地图']] as const)" :key="tab[0]" :class="{chosen:project.mode===tab[0]}" :aria-selected="project.mode===tab[0]" role="tab" @click="changeMode(tab[0])">{{tab[1]}}</button></div><span class="grow"/><button v-if="ready" :disabled="loading" @click="downloadData">更新资料</button><label class="file-button">选择资料夹<input type="file" webkitdirectory multiple aria-label="选择语言地图资料夹" :disabled="loading" @change="chooseData"/></label><button :disabled="!ready" @click="exportProject">导出工程</button><label class="file-button">打开工程<input type="file" accept=".json" @change="importProject"/></label><button :disabled="!past.length" title="撤销 Ctrl+Z" @click="undo">撤销</button><button :disabled="!future.length" title="重做 Ctrl+Shift+Z" @click="redo">重做</button><button @click="modal='help'">使用方法</button><button @click="emit('references')">来源</button></div>
 <div v-if="error" class="atlas-message error" role="alert">{{error}}<button v-if="errorRetry" @click="retryError">重试</button><button @click="error=''">收起</button></div><div v-if="notice" class="atlas-message" role="status">{{notice}}<button @click="notice=''">收起</button></div>
 <div v-if="loading" class="atlas-empty" role="status"><template v-if="downloadProgress"><p>{{downloadStatus}}</p><progress v-if="downloadProgress.total" :value="downloadProgress.loaded" :max="downloadProgress.total" aria-label="地图资料下载进度"/><button v-if="downloadProgress.phase!=='save'" @click="downloadController?.abort()">取消下载</button></template><template v-else>正在载入调查点、语言特征与井韶子整理表…</template></div>
 <div v-else-if="!resources" class="atlas-empty"><p>下载地图资料，即可查看调查点、语言现象和方言分布。</p><button class="primary" @click="downloadData">下载资料</button><p>下载后保存在本机，可离线使用。也可以在右上角选择已有资料夹。</p></div>
 <template v-else-if="resources">
 <div class="geography-toolbar"><button @click="china">中国</button><select ref="regionSelector" aria-label="省级地区" :value="provinceId" @change="chooseRegion(($event.target as HTMLSelectElement).value)"><option value="">全国</option><option v-for="a in provinces" :key="a.id" :value="a.id">{{a.name}}</option></select><select v-if="provinceId&&nextRegions.length" aria-label="下一级地区" :value="nextRegionId" @change="chooseRegion(($event.target as HTMLSelectElement).value||provinceId)"><option value="">全部市县</option><option v-for="a in nextRegions" :key="a.id" :value="a.id">{{a.name}}</option></select><select v-if="nextRegionId&&subregions.length" aria-label="县级地区" :value="subregionId" @change="chooseRegion(($event.target as HTMLSelectElement).value||nextRegionId)"><option value="">全部县区</option><option v-for="a in subregions" :key="a.id" :value="a.id">{{a.name}}</option></select><span class="grow"/><label>边界 <select v-model="level"><option value="auto">随缩放</option><option value="province">省</option><option value="city">市／县市</option><option value="district">县／乡镇区</option></select></label><fieldset class="boundary-options"><legend>叠加边界</legend><label v-for="item in boundaryLevels" :key="item"><input v-model="extraBoundaries" type="checkbox" :value="item" :aria-label="'叠加'+boundaryNames[item]"/>{{boundaryNames[item]}}</label></fieldset><label><input v-model="labels" type="checkbox"/>地名</label><button @click="openExport('svg')">SVG</button><button @click="openExport('png')">PNG</button></div>
 <div v-if="regionAvailability" class="atlas-message" role="status">{{regionAvailability}}</div>
 <div v-if="regionState.missing" class="atlas-message" role="status" :title="'原地区标识：'+region">工程原先选择的地区已调整，当前显示全国。<button @click="regionSelector?.focus()">重新选择地区</button><button @click="chooseRegion('',false)">使用全国</button></div>
 <div v-if="activeFilters.length" class="active-filters" role="status"><span>筛选：{{activeFilters.join(' · ')}} · {{count}} {{project.mode==='classification'?'条记录':'个地点'}}</span><button @click="clearFilters">清除全部筛选</button></div>
 <div class="atlas-workbench" v-resizable-panels="{key:'M19',center:'.atlas-center',centerMin:300,panels:[{selector:'.atlas-catalog',side:'left',label:'语言资料目录',initial:260,min:200,max:420},{selector:'.atlas-details',side:'right',label:'图例与地点详情',initial:280,min:220,max:440}]}">
 <aside class="atlas-catalog">
  <template v-if="project.mode==='features'"><label>显示层级<select :value="featureDetail" aria-label="分类层级" @change="changeDetail(($event.target as HTMLSelectElement).value as FeatureDetail)"><option value="broad">大类</option><option value="fine">细类</option></select></label><label>浏览范围<select :value="featureScope" aria-label="语言现象范围" @change="changeFeatureScope(($event.target as HTMLSelectElement).value as 'reviewed'|'all')"><option value="reviewed">{{featureDetail==='broad'?'有大类释义':'完整细类释义'}} · {{reviewedFeatures.length}} 项</option><option value="all">全部特征 · 编码探索</option></select></label><div class="volume-tabs"><button v-for="v in (['P','L','S'] as const)" :key="v" :class="{chosen:volume===v}" @click="changeVolume(v)">{{volumeNames[v]}}</button></div><input v-model="query" placeholder="搜索韵母、例字、项目或图号" aria-label="检索语言特征"/><div class="catalog-meta">{{featureList.length}} 项 · {{volumeNames[volume]}}卷 · {{featureScope==='reviewed'?'可读图例':'510 项原始记录'}}</div><label class="bookmark-filter"><input v-model="bookmarksOnly" type="checkbox"/>仅看收藏</label><div class="feature-list"><button v-for="f in featureList" :key="f.id" :class="{chosen:project.feature===f.id}" @click="chooseFeature(f.id)"><span class="feature-number">{{String(f.number).padStart(3,'0')}}</span><FeatureTitle :text="f.title"/></button></div><small>《汉语方言地图集》 · 调查 2000–2008</small></template>
  <template v-else-if="project.mode==='classification'"><h3>井韶子整理</h3><p class="hint">《中国语言地图集（第2版）汉语方言卷》县级分布</p><label>原始工作表<select v-model="sheet"><option v-for="s in data.classification.sheets" :key="s.id" :value="s.id">{{s.name}} · {{s.rows.length}} 条</option></select></label><input v-model="classSearch" placeholder="搜索地点或分类名称" aria-label="检索整理表"/><label v-for="(name,depth) in ['方言大区','方言区','方言片','方言小片']" :key="name">{{name}}<select :value="classFilters[depth]" @change="filterClass(depth,($event.target as HTMLSelectElement).value)"><option value="">全部</option><option v-for="value in classOptions[depth]" :key="value" :value="value">{{value===unclassifiedClassFilter?'未分':value}}</option></select></label><button @click="clearFilters">清除筛选</button><div class="summary"><b>{{classRows.length}}</b><span>条整理记录</span><b>{{countedPaths.length}}</b><span>个完整分类路径</span></div><label>统计层级<select v-model.number="classDepth"><option :value="1">大区</option><option :value="2">区</option><option :value="3">片</option><option :value="4">小片</option></select></label><button @click="modal='paths'">查看计入的分类</button><button @click="modal='ranking'">比较各省分类数量</button><small>地图标记位于县域内代表点，点击查看并存分类。</small></template>
  <template v-else-if="project.mode==='paper'"><h3>方言相似性</h3><label>结果图层<select v-model="paperMode"><option value="rgb">MDS 三维综合色图</option><option value="d1">MDS 第一维</option><option value="d2">MDS 第二维</option><option value="d3">MDS 第三维</option><option value="sharp">聚类 Type I</option><option value="heat">聚类 Type II</option></select></label><label v-if="paperMode==='sharp'||paperMode==='heat'">类别数 {{clusters}}<input v-model.number="clusters" type="range" min="2" max="10" step="1"/></label><label>距离方案<select v-model="matrixName"><option value="main">论文主结果</option><option value="type-0-0">Type 1,0 / Form 1,0</option><option value="type-0-1">Type 1,0 / Form 1,1</option><option value="type-1-0">Type 1,1 / Form 1,0</option><option value="type-1-1">Type 1,1 / Form 1,1</option></select></label><p class="hint">点击调查点，查询论文原矩阵中的相近地点。色标以全部 930 点固定。</p><div class="mds-plot"><svg viewBox="0 0 260 210" aria-label="MDS 第一维与第二维散点图"><path d="M20 10V185H250" fill="none" stroke="currentColor"/><circle v-for="({site,index}) in baseSites" :key="site.id" :cx="25+mdsScaled(index,0)*215" :cy="180-mdsScaled(index,1)*160" :r="project.selected.includes(site.id)?4:2" :fill="paperColor(index)" :stroke="project.selected.includes(site.id)?'currentColor':'none'" @click="chooseSite(site.id)"><title>{{site.name}}</title></circle><text x="120" y="205" fill="currentColor" font-size="10">MDS 第一维</text></svg></div><p class="hint">{{matrixBusy?'正在读取距离矩阵…':'完整 510 特征的预计算距离'}}</p></template>
  <template v-else><label>工程名称<input v-model="project.name" @change="checkpoint"/></label><h3>调查点与研究区域</h3><button :class="{chosen:drawMode==='point'}" @click="drawMode=drawMode==='point'?'':'point'">在地图上添加地点</button><button @click="newPoint()">输入地点坐标</button><button :class="{chosen:drawMode==='Polygon'}" @click="drawMode=drawMode==='Polygon'?'':'Polygon'">绘制研究区域</button><button :class="{chosen:drawMode==='LineString'}" @click="drawMode=drawMode==='LineString'?'':'LineString'">绘制标注线</button><button v-if="drawMode" @click="drawMode=''">退出绘制</button><p class="hint">连续点击添加顶点，双击完成区域或线。</p><label class="file-button">导入地点表<input type="file" accept=".csv,.tsv,.txt,.xlsx" @change="importTable"/></label><p class="hint">选择名称、经纬度、类别和备注列，预览后导入。</p><div class="summary"><b>{{project.customSites.length}}</b><span>个自建调查点</span></div><button @click="save">{{saving?'正在保存…':'保存到本机'}}</button></template>
 </aside>
 <div ref="mapArea" class="atlas-center" :data-background-surface="mapFullscreen?'':undefined"><div class="map-heading"><strong>{{project.mode==='classification'?'县级方言归属':project.mode==='paper'?'地理变化与聚类':project.mode==='custom'?project.name:mapCount>1?'语言现象对照':feature.title}}</strong><small v-if="project.mode==='features'&&mapCount===1&&personalObservationCount(feature)">含个人校订</small><span class="grow"/><template v-if="project.mode==='features'"><button @click="toggleBookmark">{{project.bookmarks?.includes(feature.id)?'取消收藏':'收藏本图'}}</button></template><label v-if="project.mode==='features'">对照<select v-model.number="mapCount"><option :value="1">单图</option><option :value="2">双图</option><option :value="4">四图</option></select></label><button v-if="!mapFullscreen" @click="tableOpen=!tableOpen">{{tableOpen?'收起表格':'展开表格'}}</button><template v-if="(project.mode==='classification'||project.mode==='custom')&&selectedMapPointCount"><small>已选 {{selectedMapPointCount}} 点</small><button @click="clearSelection">清空选点</button></template><button ref="mapFullscreenButton" class="map-fullscreen-button" :aria-label="mapFullscreen?'退出全屏':'全屏地图'" :title="mapFullscreen?'退出全屏（Esc）':'全屏地图'" @click="toggleMapFullscreen">{{mapFullscreen?'退出全屏':'全屏地图'}}</button></div>
  <div class="maps-grid" :class="{'maps-multiple':mapCount>1&&project.mode==='features','maps-four':mapCount===4&&project.mode==='features'}"><div v-for="(f,index) in (project.mode==='features'?mapFeatures:[feature])" :key="index" class="map-cell"><div v-if="project.mode==='features'&&mapCount>1" class="map-panel-heading"><span v-if="index===0" class="map-panel-title" :title="volumeNames[f.volume]+' '+f.number+' · '+f.title"><FeatureTitle :text="volumeNames[f.volume]+' '+f.number+' · '+f.title"/></span><select v-else v-model="extraFeatures[index-1]" :aria-label="'对照图 '+(index+1)" :title="volumeNames[f.volume]+' '+f.number+' · '+f.title"><option v-for="item in availableFeatures" :key="item.id" :value="item.id">{{volumeNames[item.volume]}} {{item.number}} · {{item.title}}</option></select><small v-if="personalObservationCount(f)">含个人校订</small></div><div class="map-content"><GeoMap :ref="el=>setMapRef(index,el)" :port="geoPort" :attributions="attributions" :points="mapPoints[index]??[]" :view="project.view" :active="active" :level="level" :extra-boundaries="extraBoundaries" :polygon-colors="polygonColors" :fit="fit" :labels="labels" :draw-mode="project.mode==='custom'&&index===0?drawMode:''" :drawings="project.drawings" @site="chooseSite" @region="chooseRegion($event,false)" @selection="project.selected=$event" @view="setView" @extent="viewExtent=$event" @draw="addDrawing" @add-point="newPoint" @error="reportError($event,'map')"/></div></div></div>
  <div v-if="tableOpen" class="atlas-table"><div class="table-toolbar"><input v-if="project.mode!=='classification'&&project.mode!=='custom'" v-model="locationQuery" placeholder="检索调查点" aria-label="检索调查点"/><label v-if="project.mode==='features'||project.mode==='paper'"><input v-model="onlySelected" type="checkbox"/>仅选中</label><label v-if="project.mode==='features'||project.mode==='paper'"><input v-model="onlyViewport" type="checkbox"/>当前视野</label><span>{{count}} {{project.mode==='classification'?'条记录':'个地点'}}</span><span class="grow"/><button @click="exportTable">导出表格</button><button :disabled="tablePage===0" @click="tablePage--">上一页</button><small>{{tablePage+1}} / {{Math.max(1,Math.ceil(count/60))}}</small><button :disabled="(tablePage+1)*60>=count" @click="tablePage++">下一页</button></div><div class="table-scroll">
   <table v-if="project.mode==='classification'"><thead data-background-surface><tr><th>省／市／县</th><th>方言分类</th><th>原表行</th></tr></thead><tbody><tr v-for="r in pageClasses" :key="r.id" :class="{selected:selectedClass===r.id}" @click="chooseClass(r)"><td>{{classValues(r,project).filter((_,i)=>[1,3,5].includes(i)).join(' / ')}}</td><td>{{classPath(classValues(r,project))}}</td><td>{{r.row}}</td></tr></tbody></table>
   <table v-else-if="project.mode==='custom'"><thead data-background-surface><tr><th>地点</th><th>经度／纬度</th><th>类别／备注</th><th>编辑</th></tr></thead><tbody><tr v-for="p in project.customSites.slice(tablePage*60,(tablePage+1)*60)" :key="p.id" @click="focusSite(p.id)"><td>{{p.name}}</td><td>{{p.lon.toFixed(4)}}, {{p.lat.toFixed(4)}}</td><td>{{p.value}} · {{p.note}}</td><td><button @click.stop="editPoint(p.id)">编辑</button></td></tr></tbody></table>
   <table v-else><thead data-background-surface><tr><th>选点</th><th>调查点</th><th>{{project.mode==='paper'?'论文结果':feature.title}}</th><th>经度／纬度</th></tr></thead><tbody><tr v-for="({site,index}) in pageSites" :key="site.id" :class="{selected:selectedSite===site.id}" @click="chooseSite(site.id)"><td><input :checked="project.selected.includes(site.id)" type="checkbox" :aria-label="'选择 '+site.name" @click.stop @change="project.selected=project.selected.includes(site.id)?project.selected.filter(id=>id!==site.id):[...project.selected,site.id]"/></td><td><button class="text-button" @click.stop="focusSite(site.id)">{{site.name}}</button></td><td><FeatureTitle :text="project.mode==='paper'?paperValue(index):valueLabel(observation(data,project,feature.id,index),feature,site.id)"/><small v-if="project.mode==='features'&&featureDetail==='fine'" class="category-code">{{observation(data,project,feature.id,index)}}</small></td><td>{{site.lon.toFixed(4)}}, {{site.lat.toFixed(4)}}</td></tr></tbody></table>
  </div></div>
 </div>
 <aside class="atlas-details">
  <template v-if="project.mode==='classification'"><h3>整理记录</h3><template v-if="currentClass"><b>{{classValues(currentClass,project)[5]}}</b><p>{{classPath(classValues(currentClass,project))}}</p><p class="hint">{{currentClass.sheet}} · 第 {{currentClass.row}} 行<br/>{{currentClass.admin?'已对应行政区底图':'保留在整理表中，地名尚未对应底图'}}</p><button @click="editClass">编辑这条记录</button><details><summary>原始记录</summary><dl><template v-for="(name,i) in data.classification.columns" :key="name"><dt>{{name}}</dt><dd>{{currentClass.original[i]??'—'}}</dd></template></dl></details></template><p v-else class="hint">点击表格记录，查看分类、原表位置并编辑。</p><hr/><h3>当前范围</h3><p>{{classMarkers.length}} 个已定位行政单元，{{classRows.filter(r=>!r.admin).length}} 条未定位记录。</p><p class="hint">区域底色汇总当前行政区内已对应的整理记录，多类用蓝灰色表示。</p><p class="hint">彩色小点表示当前层级的单一分类，蓝灰色大点表示同一地点兼有多类。分类数量按完整父级路径计数。</p></template>
  <template v-else-if="project.mode!=='custom'"><div class="section-heading"><h3>图例</h3><button v-if="category" @click="category=''">全部类别</button></div><p v-if="project.mode==='paper'&&!legend.length" class="hint">{{paperMode==='rgb'?'红、绿、蓝分别对应三个 MDS 维度，按全部调查点的范围映射。':'当前 MDS 维度：负值为红色，零值为白色，正值为蓝色。' }}</p><div class="legend"><button v-for="item in legend" :key="item.code" :class="{chosen:category===item.code}" :title="project.mode==='features'?(featureDetail==='fine'?'分类编码：'+item.code:item.label):undefined" @click="project.mode==='features'&&(category=category===item.code?'':item.code)"><span class="swatch" :style="{background:item.color}"/><span class="legend-word"><FeatureTitle :text="item.label"/></span><small class="legend-count">{{item.count}}{{project.mode==='features'?' 点':''}}</small></button></div><template v-if="project.mode==='features'"><p v-if="featureDetail==='broad'" class="hint category-coverage">本图已对应 {{feature.groupReview?.verifiedGroups??0}} 个大类。图例按地点计数，同点同类只计一次。</p><p v-else class="hint category-coverage">细类释义 {{feature.categoryReview?.verified??Object.keys(feature.labels).length}} / {{feature.categories.length}} 已核对 · 数量为地点数</p><div v-if="featureDetail==='broad'&&pendingSites" class="pending-records"><p>{{pendingSites}} 个地点含待核记录。空心点保留未对应地点，虚线边框表示同点还有部分记录待对应。</p><button :class="{chosen:category===pendingBroadSites}" @click="category=category===pendingBroadSites?'':pendingBroadSites">{{category===pendingBroadSites?'返回全部地点':'查看待核地点'}}</button></div><p v-if="featureDetail==='broad'&&feature.groupNote" class="category-note">{{feature.groupNote}}</p><p v-if="feature.categoryNote" class="category-note"><FeatureTitle :text="feature.categoryNote"/></p><details><summary>图号与释义</summary><p>{{volumeNames[feature.volume]}}卷 · 图 {{feature.number}} · PDF 第 {{feature.page}} 页</p><p v-if="featureDetail==='broad'" class="hint">大类对应覆盖 {{feature.groupReview?.verifiedCodes??0}} / {{feature.categories.length}} 个原始编码。地点记录与原图的差异另行核对。</p><p class="hint">《汉语方言地图集》。分类编码来自论文数据，大类按原书标题或已核实的共同特征概括。细类释义另行核对。</p><button @click="labelCode=feature.categories[0];labelText=editableLabel(labelCode);modal='label'">填写类别释义</button></details></template>
  <hr/><h3>{{currentSite?.name??'调查点详情'}}</h3><template v-if="currentSite"><p class="hint">{{currentSite.id}} · {{currentSite.lon.toFixed(5)}}, {{currentSite.lat.toFixed(5)}}<br/>{{currentSite.admin?adminIndex.get(currentSite.admin)?.name:'调查位置保留原始坐标'}}</p><dl v-if="project.mode==='paper'" class="paper-details"><template v-for="(v,i) in data.paper.points[currentSiteIndex].mds" :key="i"><dt>MDS {{i+1}}</dt><dd>{{v.toFixed(6)}}</dd></template><dt>Type I · {{clusters}} 类</dt><dd>{{data.paper.points[currentSiteIndex].sharp[clusters-2]}}</dd><dt>Type II · {{clusters}} 类</dt><dd>{{data.paper.points[currentSiteIndex].heat[clusters-2]}}</dd></dl><p v-if="project.mode==='features'"><FeatureTitle :text="valueLabel(observation(data,project,feature.id,currentSiteIndex),feature,currentSite?.id)"/><small v-if="featureDetail==='fine'" class="category-code">编码：{{observation(data,project,feature.id,currentSiteIndex)??'原值待核'}}</small></p><button v-if="project.mode==='features'" @click="editObservation">编辑当前特征</button><button v-if="project.mode==='features'&&Object.hasOwn(project.edits,currentSite.id+':'+feature.id)" @click="restoreObservation">恢复原值</button><details><summary>地图集原值与全部特征</summary><p class="raw-value">{{rawValue()}}</p><div class="all-features"><button v-for="r in allSiteFeatures" :key="r.feature.id" @click="changeMode('features');chooseFeature(r.feature.id)"><FeatureTitle :text="r.feature.title"/> <FeatureTitle :text="valueLabel(r.value,r.feature,currentSite?.id)"/></button></div></details><template v-if="project.mode==='paper'"><h3>相近调查点</h3><div v-for="n in nearby" :key="n.index" class="nearby"><button class="text-button" @click="focusSite(data.sites[n.index].id)">{{data.sites[n.index].name}}</button><small>{{n.distance.toFixed(5)}}</small><button @click="comparePair(data.sites[n.index].id)" :aria-label="'比较 '+currentSite.name+'与'+data.sites[n.index].name">对比</button></div></template></template><p v-else class="hint">点击地图或表格中的调查点。</p>
  <hr/><div class="section-heading"><h3>选点 {{project.selected.length}}</h3><button :disabled="!project.selected.length" @click="clearSelection">清空</button></div><p class="hint">{{project.selected.slice(0,8).map(id=>data.sites[siteIndex.get(id)??-1]?.name).filter(Boolean).join(' · ')}}</p><button :disabled="selectedIndices.length<2||selectedIndices.length>8" @click="openComparison">比较 2–8 个地点</button><p v-if="selectedIndices.length>8" class="hint">当前选中 {{selectedIndices.length}} 点。可导出表格，或缩小选择后逐项比较。</p></template>
  <template v-else><h3>工程内容</h3><p>{{project.customSites.length}} 个自建点<br/>{{Object.keys(project.edits).length}} 项特征校订<br/>{{Object.keys(project.classEdits).length}} 条分类校订</p><p class="hint">编辑保存在当前工程中。导出工程可以带走校订、图层、选点和视野。</p><button @click="exportProject">导出完整工程</button></template>
 </aside></div><div class="atlas-footnote"><span>{{project.mode==='classification'?'井韶子整理 · 原表可追溯':'Huang 等（2024） · 930 调查点 · 510 特征'}}</span><span>{{saving?'正在保存工程…':'本机工程'}} · {{selectedAdmin?.name??'全范围'}}</span></div>
 </template>

<ModalDialog v-if="modal==='export'" :title="'导出 '+exportFormat.toUpperCase()+' 图片'" @close="!exportBusy&&(modal='')">
 <div class="export-options"><label><input v-model="exportOptions.legend" type="checkbox"/>包含分类图例</label><label><input v-model="exportOptions.scale" type="checkbox"/>包含比例尺</label><label>地名<select v-model="exportOptions.names" aria-label="导出地名"><option value="none">不显示</option><option value="all">全部显示的点</option><option value="selected">仅已选点</option></select></label><fieldset><legend>行政边界（可多选）</legend><label v-for="item in boundaryLevels" :key="item"><input v-model="exportOptions.boundaries" type="checkbox" :value="item" :aria-label="'导出'+boundaryNames[item]"/>{{boundaryNames[item]}}</label></fieldset><p class="hint">省界为粗线，市界为中线，县界为细线。导出范围沿用当前地图视野。</p></div>
 <template #footer><button :disabled="exportBusy" @click="modal=''">取消</button><button class="primary" :disabled="exportBusy" @click="exportMap(exportFormat)">{{exportBusy?'正在导出…':'导出图片'}}</button></template>
</ModalDialog>
<ModalDialog v-if="modal==='observation'" :title="currentSite?.name+' · '+feature.title" @close="modal=''"><label>类别／有序变体<input v-model="editText" class="full-input"/></label><p class="hint">多个变体以 # 分隔。原始值：{{rawValue()}}</p><template #footer><button @click="modal=''">取消</button><button class="primary" @click="applyObservation">保存校订</button></template></ModalDialog>
<ModalDialog v-if="modal==='classification'" title="编辑整理记录" wide @close="modal=''"><div class="edit-grid"><label v-for="(name,i) in data.classification.columns" :key="name">{{name}}<input v-model="editValues[i]" :readonly="i<6"/></label></div><template #footer><button @click="modal=''">取消</button><button class="primary" @click="applyClass">保存到工程</button></template></ModalDialog>
<ModalDialog v-if="modal==='label'" title="编辑当前特征的类别释义" @close="modal=''"><div class="edit-grid"><label>分类号<select v-model="labelCode" @change="labelText=editableLabel(labelCode)"><option v-for="c in feature.categories" :key="c">{{c}}</option></select></label><label>释义／IPA<input v-model="labelText"/></label></div><template #footer><button class="primary" @click="project.labels[feature.id]={...project.labels[feature.id],[labelCode]:labelText};checkpoint();modal=''">保存释义</button></template></ModalDialog>
<ModalDialog v-if="modal==='point'" :title="pointDraft.id?'编辑调查点':'新增调查点'" @close="modal=''"><div class="edit-grid"><label>地点<input v-model="pointDraft.name"/></label><label>经度（WGS84）<input v-model.number="pointDraft.lon" type="number" step="0.00001"/></label><label>纬度（WGS84）<input v-model.number="pointDraft.lat" type="number" step="0.00001"/></label><label>类别／IPA<input v-model="pointDraft.value"/></label><label>备注<input v-model="pointDraft.note"/></label></div><template #footer><button @click="modal=''">取消</button><button class="primary" @click="applyPoint">保存地点</button></template></ModalDialog>
<ModalDialog v-if="modal==='paths'" :title="'计入的完整分类路径 · '+countedPaths.length" wide @close="modal=''"><div class="path-list"><button v-for="p in countedPaths" :key="p.path" @click="selectPath(p.path)"><span>{{p.path}}</span><small>{{p.rows.length}} 条</small></button></div></ModalDialog>
<ModalDialog v-if="modal==='ranking'" title="各省分类数量" wide @close="modal=''"><p class="hint">来源表：{{data.classification.sheets.find(s=>s.id===sheet)?.name}}。按完整父级路径统计{{['','大区','区','片','小片'][classDepth]}}，点击省份查看计数依据。</p><div class="path-list"><button v-for="p in provinceRanking" :key="p.name" @click="chooseRegion(provinces.find(a=>a.name===p.name)?.id??'');classFilters=['','','',''];classSearch='';modal='paths'"><span>{{p.name}}</span><meter :value="p.count" min="0" :max="provinceRanking[0]?.count??1"/><b>{{p.count}}</b><small>{{p.rows}} 条记录</small></button></div></ModalDialog>
<ModalDialog v-if="compareOpen" title="调查点对照" wide @close="compareOpen=false">
<div class="comparison-sites"><label v-for="(i,index) in selectedIndices.slice(0,8)" :key="index">地点 {{index+1}}<select :value="data.sites[i].id" :aria-label="'对照地点 '+(index+1)" @change="replaceComparedSite(index,($event.target as HTMLSelectElement).value)"><option v-for="site in data.sites" :key="site.id" :value="site.id" :disabled="project.selected.includes(site.id)&&site.id!==data.sites[i].id">{{site.name}} · {{site.id}}</option></select></label></div>
<div class="comparison-controls"><label>项目范围<select v-model="compareVolume" aria-label="比较项目范围"><option value="">全部 510 项</option><option v-for="v in (['P','L','S'] as const)" :key="v" :value="v">{{volumeNames[v]}}</option></select></label><label>记录关系<select v-model="compareStatus" aria-label="比较记录关系"><option value="">全部</option><option value="different">记录不同</option><option value="same">记录相同</option><option value="missing">含缺值</option></select></label><button @click="exportComparison">导出对照表</button></div>
<p class="comparison-summary">{{groupedComparisons.length}} 项：记录相同 {{comparisonCounts.same}} 项，记录不同 {{comparisonCounts.different}} 项，含缺值 {{comparisonCounts.missing}} 项。当前显示 {{comparisons.length}} 项。</p><p class="hint">按当前工程中的完整记录比较，保留有序变体。{{Object.keys(project.edits).length?'含个人校订。':''}}点击项目名称查看分布地图。</p>
<p class="hint">含义按{{featureDetail==='broad'?'大类':'细类'}}显示；记录相同与不同按完整原始编码判断。</p><div class="comparison-scroll"><table><thead data-background-surface><tr><th>语言特征</th><th v-for="i in selectedIndices.slice(0,8)" :key="i">{{data.sites[i].name}}</th></tr></thead><tbody><tr v-for="r in comparisonPageRows" :key="r.feature.id"><td><small>{{volumeNames[r.feature.volume]}} {{r.feature.number}}</small><br/><button class="text-button" @click="changeMode('features');chooseFeature(r.feature.id);compareOpen=false">{{r.feature.title}}</button></td><td v-for="(v,i) in r.values" :key="i"><FeatureTitle :text="valueLabel(v,r.feature,data.sites[selectedIndices[i]].id)"/><small v-if="featureDetail==='fine'" class="category-code">{{v}}</small></td></tr></tbody></table><p v-if="!comparisons.length" class="hint">当前范围没有这类记录。</p></div><div v-if="comparisons.length" class="comparison-pagination"><span>第 {{comparisonPage+1}} / {{comparisonPageCount}} 页 · 每页 60 项</span><button aria-label="地点对照上一页" :disabled="comparisonPage===0" @click="comparisonPage--">上一页</button><button aria-label="地点对照下一页" :disabled="comparisonPage>=comparisonPageCount-1" @click="comparisonPage++">下一页</button></div><details v-if="matrix"><summary>论文原距离矩阵</summary><p class="hint">{{matrixName}} 方案，使用论文原始数据的预计算距离。</p><table><thead data-background-surface><tr><th>调查点</th><th v-for="j in selectedIndices.slice(0,8)" :key="j">{{data.sites[j].name}}</th></tr></thead><tbody><tr v-for="i in selectedIndices.slice(0,8)" :key="i"><th>{{data.sites[i].name}}</th><td v-for="j in selectedIndices.slice(0,8)" :key="j">{{matrix[i*930+j].toFixed(5)}}</td></tr></tbody></table></details></ModalDialog>
<ModalDialog v-if="modal==='import-project'&&pendingProject" title="打开地图工程" @close="modal=''"><p>{{pendingProject.name}}</p><p>{{pendingProject.customSites.length}} 个自建点，{{Object.keys(pendingProject.edits).length}} 项特征校订，{{Object.keys(pendingProject.classEdits).length}} 条分类校订。</p><template #footer><button @click="modal=''">取消</button><button class="primary" @click="applyProject">打开工程</button></template></ModalDialog>
<ModalDialog v-if="modal==='import-table'" title="导入地点表" wide @close="modal=''"><label>工作表<select v-model.number="importSheet" @change="changeImportSheet"><option v-for="(name,i) in importBook?.names" :key="name" :value="i">{{name}}</option></select></label><div class="edit-grid"><label v-for="(field,i) in ['地点','经度','纬度','类别／IPA','备注']" :key="field">{{field}}<select v-model.number="importColumns[i]"><option v-for="(column,c) in importRows[0]" :key="c" :value="c">{{column||'第 '+(c+1)+' 列'}}</option></select></label></div><p>首行作为列名，{{importPreview.length}} 条数据，{{importPreview.filter(r=>!r.valid).length}} 条需要修正。坐标使用 WGS84。</p><div class="comparison-scroll"><table><tbody><tr v-for="(r,i) in importPreview.slice(0,20)" :key="i"><td>{{r.name}}</td><td>{{r.lon}}</td><td>{{r.lat}}</td><td>{{r.value}}</td><td>{{r.valid?'可导入':'坐标或名称无效'}}</td></tr></tbody></table></div><template #footer><button @click="modal=''">取消</button><button class="primary" @click="applyTable">导入全部地点</button></template></ModalDialog>
<ModalDialog v-if="modal==='help'" title="语言地图使用方法" wide @close="modal=''"><div class="help-text"><p>首次使用点击“下载资料”，下载并校验后自动显示地图；再次打开复用本机资料。也可点击“选择资料夹”，选择已有的 geolinguistics-data 文件夹。资料保存在当前账号工作区的本机存储中，重新打开可继续使用。Windows 免安装版也可把资料夹放在 EXE 旁自动读取。macOS 与网页使用同一资料夹，地图和编辑在本机处理。</p><p>方言分布：浏览井韶子整理的县级数据。选择原始工作表，按省市县或大区、区、片、小片筛选。分类数量按完整父级路径计数，可展开实际计数清单。</p><p>方言相似性：查看论文已有的 MDS、聚类与距离结果。选择调查点后显示相近地点，点击“对比”可查看两地各项记录。可按语音、词汇、语法筛选相同、不同或含缺值的项目，并导出对照表。</p><p>语言现象：默认按大类显示已有核实含义的现象，右侧列出本图完整程度。大类汇总有明确对应的编码，同一地点的多个编码属于同一大类时只计一次；兼有多个大类的地点会计入各类。切到细类可查看已有的具体释义，未核实部分保留编码。点击图例筛选地点，支持收藏、双图或四图对照。切到“全部特征 · 编码探索”可浏览全部 510 项记录；未核实的含义保留编码，出处中列明原书图号和 PDF 页码。</p><p>地图：滚轮缩放，Shift 拖动框选。省、市、县选择会筛选资料，直接拖动缩放只改变视野。勾选当前视野后，表格跟随地图范围。</p><p>我的研究地图：添加地点、IPA、备注，绘制区域与标注线，导入地点表。编辑自动保存在本机，Ctrl+S 重试保存，Ctrl+Z 撤销。导出工程保留个人编辑；PNG、SVG 和表格用于研究输出。</p><button @click="modal='';emit('help')">打开完整使用说明</button></div></ModalDialog>
</ModuleFrame>
</template>

